mapper.select:
SELECT sku_id, spu_code, product_name, sku_code, sku_name, purchase_unit, SUM(order_count)::bigint AS order_count, SUM(planned_quantity) AS planned_quantity, SUM(order_amount) AS order_amount FROM report_purchase_daily_item WHERE report_date = #{query.reportDate}
AND warehouse_id IN #{id}
AND FALSE
AND purchaser_id IN #{id}
AND FALSE
AND warehouse_id = #{query.warehouseId}
AND (product_name ILIKE CONCAT('%', #{query.keyword}, '%') OR spu_code ILIKE CONCAT('%', #{query.keyword}, '%') OR sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
GROUP BY sku_id, spu_code, product_name, sku_code, sku_name, purchase_unit ORDER BY sku_id, purchase_unit, spu_code, product_name, sku_code, sku_name
